ecision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99687b23-6e0e-528d-8d3d-f789e1117814"}, {"title": "黄福出外督理漕运", "description": "宣德4年（年号对照1429年）四月，黄福出外督理漕运。", "start_year": 1429, "end_year": 1429, "time_original": "宣德4年（年号对照1429年）四月；公元年核为1429年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "2e63e085-e4ec-575f-b299-5f7fd3783b6e"}, {"title": "明廷审录在押囚犯", "description": "宣德四年五月壬子，朝廷审录在押囚犯。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年五月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "109e83c0-21bb-51d1-8ec2-0809e86b8ee4"}, {"title": "明廷取消文官贪赃赎罪的旧例", "description": "宣德四年六月甲午，朝廷废止原先允许文官犯贪赃罪后赎罪的规定。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年六月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "40768167-8e81-5350-8ddf-afd613a3f760"}, {"title": "开平遭到进犯，镇抚张信等人阵亡", "description": "宣德四年六月己亥，敌军进犯开平，镇抚张信等人在交战中身亡。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年六月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3114e297-af51-50dd-a99b-dcf45520fe53"}, {"title": "薛禄赴开平督办军饷", "description": "宣德四年六月庚子，朝廷命薛禄到开平督办军饷。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年六月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2630324c-944c-56af-a8df-a