9, "time_original": "宣德四年十月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1b62c499-5239-59b0-9ed5-afec439f9978"}, {"title": "陈山改为专门教授小内使读书", "description": "宣德4年（1429年）十月，陈山改为专门教授小内使读书。", "start_year": 1429, "end_year": 1429, "time_original": "宣德4年（1429年）十月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "2f030133-98e5-5eef-9159-823574d1df09"}, {"title": "张瑛改任南京礼部尚书", "description": "宣德4年（1429年）十月，张瑛改任南京礼部尚书。", "start_year": 1429, "end_year": 1429, "time_original": "宣德4年（1429年）十月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "b1f71573-ef0b-5070-9886-bd88b2cd28c9"}, {"title": "明宣宗在近郊检阅军队", "description": "宣德四年十月甲午，明宣宗朱瞻基前往近郊检阅军队。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年十月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c13d3bbe-44f3-5dda-9936-7a3788da150d"}, {"title": "明宣宗在峪口打猎", "description": "宣德四年十月乙未，明宣宗朱瞻基在峪口狩猎。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年十月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36fa6f51-20a1-5b5a-8697-f49a01c07330"}, {"title": "明宣宗出巡后返回宫中", "description": "宣德四年十月戊戌，明宣宗朱瞻基返回宫中。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年十月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cdf03673-5e06-59d9-889e-6b1fd3ce6fec"}, {"title": "薛禄、吴克忠率军巡视宣府", "description": "宣德四年十一月癸卯，薛禄与恭顺侯吴克忠率兵巡视宣府。", "start_year": 1429, "end_year": 1429, "time_original": "宣德四年十一月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd04ad6f-f6dd-5383-b292-8bdc089f64e3"}, {"title": "京师发生地震", "description": "宣德四年十二月乙亥，京师发生地震。", "start_year": 1430, "end_year": 1430, "time_original": "宣德四年十二月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d11d98bf-904c-58f9-93b3-3e29e6c92ea8"}, {"title": "明廷停止宦官在松花江督办造船", "description": "宣德四年十二月壬辰，朝廷停止由宦官在松花江督办的造船事务。", "start_year": 1430, "end_year": 1430, "time_original": "宣德四年十二月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "44b61c30-d83e-5cfe-8eec-df76f02f3964"}, {"title": "本纪汇记宣德四年多地入贡", "description": "宣德四年，爪哇、占城、琉球、榜葛剌、哈密、土鲁番、亦力把里和撒马儿罕入贡。 按原历纪年，事情发生在公元1429至1430年之间。", "start_year": null, "end_year": null, "time_original": "宣德四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7339fde9-4780-5f59-a66d-558d4ac7c797"}, {"title": "明宣宗在南郊祭祀天地", "description": "宣德五年正月癸丑，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00739432-e9ce-57e4-9a16-3d6d9368096e"}, {"title": "夏原吉去世", "description": "宣德5年（年号对照1430年）正月，夏原吉去世。", "start_year": 1430, "end_year": 1430, "time_original": "宣德5年（年号对照1430年）正月；公元年核为1430年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "8b1827d8-df08-5891-bbfa-8fd681db7d42"}, {"title": "明廷停止工部采木", "description": "宣德五年二月壬辰，朝廷停止工部采集木材的事务。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年二月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c502ecd-2fbc-5183-b8cd-2723c7808de6"}, {"title": "明廷颁宽恤令，减轻灾民、流民、工匠等负担", "description": "宣德五年二月癸巳，朝廷颁布宽恤令，要求察看灾情、放宽养马事务、免去积欠薪草、接纳流民并准其免役一年、停止采买、把官田原征额减去三成，并要求善待工匠、规范仓官收纳、审慎办理刑狱。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年二月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f962b19e-e24e-5f2b-a7cb-1f0335150a6e"}, {"title": "明宣宗陪皇太后谒陵", "description": "宣德五年二月乙未，明宣宗朱瞻基陪皇太后张氏前往拜谒陵寝。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "327b5ef1-e580-5fbc-b2c8-21ca9df94804"}, {"title": "明宣宗在途中询问农事，令赏赐农民宝钞", "description": "宣德五年三月戊申，明宣宗朱瞻基在途中见有人耕田，下马询问农事，并试着推了三次农具。他对随从官员说，自己推三次已感到劳累，何况百姓终年劳作，遂命给经过地方的农民发放宝钞。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年三月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3966af8f-8e38-597f-a9cb-4d620deecad0"}, {"title": "明宣宗返回宫中", "description": "宣德五年三月己酉，明宣宗朱瞻基返回宫中。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年三月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ffe479e2-e3ca-57fd-bf37-6d6d58b58fc7"}, {"title": "李琦返回，黎利上表请封", "description": "宣德五年三月辛亥，李琦出使后回朝。本纪随后记黎利声称陈氏已经没有后人，并向明廷上表请求册封。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年三月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e041eb04-8803-50d5-928a-531ba46573b7"}, {"title": "明廷减免山西上年灾田田租", "description": "宣德五年三月丙辰，朝廷减免山西上年受灾田地所涉田租。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年三月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a6468d3-0ad6-5a15-b14c-0196792b08c7"}, {"title": "朝廷授予林震等人不同等第的进士资格", "description": "宣德五年三月丁巳，明廷给林震等人授予不同等第的进士资格。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年三月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "70a827c4-7fb1-568d-a7bc-6c0ada642693"}, {"title": "薛禄带兵修筑赤城等处城堡", "description": "宣德五年四月戊寅，薛禄率部修筑赤城、鵰鹗、云州、独石、团山的城堡。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年四月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6230bb67-d1ee-543d-96cc-68abddb2023e"}, {"title": "明廷规定追缴贪赃官吏的封授诰敕", "description": "宣德五年五月癸卯，朝廷规定收回贪赃官员所得的封授诰敕，并将这项做法定为法令。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年五月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "37bca432-9156-5aed-8868-ed71d4fe31fc"}, {"title": "明廷修筑预备仓，拨公款购买储粮", "description": "宣德五年五月丙辰，朝廷修筑预备仓，拨出公款购买粮食，以备荒年。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年五月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "637550c6-8d24-5180-b114-decdd30e84ee"}, {"title": "况钟、何文渊等九人被提拔为知府", "description": "宣德五年五月癸亥，朝廷提拔郎中况钟、御史何文渊等九人担任知府，发下任命文书，派他们赴任。卷末校记说明何文渊官职原脱「御史」二字。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年五月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "457cd1d4-8ecd-5532-877c-b3a348ec5de9"}, {"title": "明宣宗派官捕蝗，告诫户部防止官员扰民", "description": "宣德五年六月己卯，明宣宗派官员在京畿附近捕蝗，提醒户部往年有负责捕蝗的使者扰害百姓，并写了捕蝗诗告诫官员。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年六月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "26fe7918-4022-5551-a078-543ab3e7c2c5"}, {"title": "明廷考查各地守令", "description": "宣德五年七月癸亥，朝廷对各地知府、知县等守令进行甄别考查。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年七月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "485a5b15-4421-5423-9f23-c86323676f61"}, {"title": "本纪记初一日食因阴雨未见，明宣宗拒绝庆贺", "description": "宣德五年八月初一，本纪记有日食，当时因阴雨未能见到。礼官请求上表庆贺，明宣宗未准。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年八月己巳朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "97f9f124-917c-5f62-8f47-07f6180e9e8e"}, {"title": "于谦、周忱等六人受任侍郎，分赴各地巡抚", "description": "宣德五年九月丙午，明廷提拔御史于谦、长史周忱等六人为侍郎，分派他们巡抚两京及山东、山西、河南、江西、浙江、湖广。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年九月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "90c8506d-1a87-51be-8a41-09fe08cbe9aa"}, {"title": "明宣宗前往近郊巡视", "description": "宣德五年九月乙卯，明宣宗朱瞻基到近郊巡视。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年九月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6903219-06ed-5e67-8a0b-911126bf3bff"}, {"title": "明宣宗巡视近郊后回宫", "description": "宣德五年九月己未，明宣宗朱瞻基返回宫中。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年九月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd807c24-681d-5500-99ad-a81d7c7abeba"}, {"title": "阿鲁台进犯辽东，皇甫斌战死", "description": "宣德五年十月乙亥，阿鲁台率部进犯辽东。辽海卫指挥同知皇甫斌在交战中身亡。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年十月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b0b58d9e-61a1-5853-9f49-cf983da92995"}, {"title": "明宣宗到近郊巡视", "description": "宣德五年十月丙子，明宣宗朱瞻基前往近郊巡视。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年十月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2118c87a-97d8-57d8-8f14-e1d94222bd2a"}, {"title": "明宣宗在坌道打猎", "description": "宣德五年十月己卯，明宣宗朱瞻基在坌道狩猎。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年十月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "45bdfbe4-bcfd-541d-87a9-8d9125e9670e"}, {"title": "明宣宗到洗马林巡阅城堡防务", "description": "宣德五年十月丙戌，明宣宗朱瞻基到达洗马林，巡查各处城堡的兵备。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年十月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c94e361-f6b8-5426-9062-221ad5a633e7"}, {"title": "明宣宗巡阅后回宫", "description": "宣德五年十月壬辰，明宣宗朱瞻基返回宫中。", "start_year": 1430, "end_year": 1430, "time_original": "宣德五年十月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a77900f9-0658-5a73-b047-1a9f824576b8"}, {"title": "本纪记曲先战事平息", "description": "宣德五年十二月癸巳，据《明史》本纪，曲先一带与明廷的战事平息。", "start_year": 1431, "end_year": 1431, "time_original": "宣德五年十二月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e2a14ec-b713-5d52-9bfb-81208e9a06bb"}, {"title": "明廷下令追究久拖囚犯案件的官员", "description": "宣德五年闰十二月己未，朝廷告谕各级官署，久拖囚犯案件、长时间羁押而未处理的，要追究有关官员责任。", "start_year": 1431, "end_year": 1431, "time_original": "宣德五年闰十二月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "66d54809-8775-5f5e-a0de-8692ab4277d2"}, {"title": "本纪汇记宣德五年多地入贡", "description": "宣德五年，占城、琉球、爪哇、瓦剌、哈密、罕东、土鲁番、撒马儿罕和亦力把里入贡。 按原历纪年，事情发生在公元1430至1431年之间。", "start_year": null, "end_year": null, "time_original": "宣德五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bee26791-408a-50c2-9e21-d3dc94bcb6bf"}]'::jsonb)
